/*---
es5id: 10.6-10-c-ii-1-s
description: >
    arguments[i] remains same after changing actual parameters in
    strict mode
flags: [onlyStrict]
---*/

function foo(a,b,c)
{
  a = 1; b = 'str'; c = 2.1;
  return (arguments[0] === 10 && arguments[1] === 'sss' && arguments[2] === 1);
}

assert(foo(10, 'sss', 1), 'foo(10, \"sss\", 1) !== true');

